    <div class="forgot-password-container">
        <div class="header-container">
            <div class="logo-container">
        <l-img :src="appLogo" :w="logoSize.width" :h="logoSize.height" />
        <span class="logo-text" :style="{ fontSize: logoTextSize }">{{ appName }}</span>
      </div>
        <div class="content-container">
            <!-- Step 1: 输入邮箱 -->
            <div v-if="currentStep === 1" class="form-container">
                <div class="back-button" @click="clickBackToLogin">
                    <el-icon color="#6B7280" size="16"><Back /></el-icon>
                    <span>{{ $t('back') }}</span>
                </div>

                <span class="title">{{ $t('resetYourPassword') }}</span>
                <span class="description">{{ $t('enterEmailForCode') }}</span>

                <div class="form-group">
                    <span class="form-label">{{ $t('emailAddress') }}</span>
                    <div class="input-container" :class="{ 'input-error': emailError }">
                        <input
                            type="email"
                            v-model="email"
                            :placeholder="$t('emailPlaceholder')"
                            @blur="validateEmail"
                        />
                    </div>
                    <span v-if="emailError" class="error-message">{{ emailError }}</span>
                </div>

                <l-button
                    :text="$t('sendVerificationCode')"
                    :loadingText="$t('loading')"
                    :disabled="!isEmailValid || isLoading"
                    :loading="isLoading"
                    @onClick="clickSendVerificationCode"
                />

                <div class="terms-container">
                    <span class="terms-text">
                        {{ $t('continueAgree', { appName: appName }) }}
                        <span @click="clickTermsOfService" class="link">{{ $t('termsOfService') }}</span>
                        {{ $t('and') }}
                        <span @click="clickPrivacyPolicy" class="link">{{ $t('privacyPolicy') }}</span>
                    </span>
                </div>
            </div>

            <!-- 已移除第2步，直接到第3步: 创建新密码 -->
            <div v-if="currentStep === 3" class="form-container">
                <div class="back-button" @click="clickBackToVerify">
                    <el-icon color="#6B7280" size="16"><Back /></el-icon>
                    <span>{{ $t('back') }}</span>
                </div>

                <span class="title">{{ $t('createNewPassword') }}</span>
                <span class="description">{{ $t('createSecurePassword') }}</span>

                <!-- 错误提示 -->
                <div v-if=" newPassword && confirmPassword && (passwordsNotMatch || passwordTooShort || passwordTooLong)" class="error-alert">
                    <l-img :src="'/static/images/password-error.png'" w="18px" h="18px" />
                    <span v-if="passwordsNotMatch">{{ $t('passwordsNotMatch') }}</span>
                    <span v-else-if="passwordTooShort">{{ $t('passwordTooShortTip') }}</span>
                    <span v-else-if="passwordTooLong">{{ $t('passwordTooLongTip') }}</span>

                </div>

                <div class="form-group">
                    <span class="form-label">{{ $t('newPassword') }}</span>
                    <div class="input-container">
                        <input
                            :type="showPassword ? 'text' : 'password'"
                            v-model="newPassword"
                            :placeholder="$t('createNewPasswordPlaceholder')"
                            @blur="validatePasswords"
                        />
                    </div>
                    <span class="password-requirement">{{ $t('passwordRequirement') }}</span>
                </div>

                <div class="form-group">
                    <span class="form-label">{{ $t('confirmPassword') }}</span>
                    <div class="input-container">
                        <input
                            :type="showPassword ? 'text' : 'password'"
                            v-model="confirmPassword"
                            :placeholder="$t('confirmPasswordPlaceholder')"
                            @blur="validatePasswords"
                        />
                    </div>
                </div>
                <div class="form-group">
                    <span class="form-label">{{ $t('verificationCode') }}</span>
                    <div class="input-container" :class="{ 'input-error': verificationCodeError }">
                        <input
                            type="text"
                            v-model="verificationCode"
                            :placeholder="$t('enterVerificationCodePlaceholder')"
                            maxlength="8"
                            @blur="validateVerificationCode"
                        />
                    </div>
                    <span v-if="verificationCodeError" class="error-message">{{ verificationCodeError }}</span>
                </div>

                <span class="sent-to-email">{{ $t('verificationSentTo', { email }) }}</span>

                <div class="show-password">
                    <div class="checkbox" @click="toggleShowPassword">
                        <div class="checkbox-inner" :class="{ 'checked': showPassword }">
                            <l-img v-if="showPassword" :src="'/static/images/password-show.png'" w="12px" h="12px" />
                            <l-img v-else :src="'/static/images/password-hide.png'" w="14px" h="14px" />
                        </div>
                    </div>
                    <span @click="toggleShowPassword">{{ $t('showPassword') }}</span>
                </div>

                <l-button
                    :text="$t('resetPassword')"
                    :loadingText="$t('loading')"
                    :disabled="!isAllInputsValid || isLoading"
                    :loading="isLoading"
                    @onClick="clickResetPassword"
                />

                <div class="resend-container">
                  <span class="text-button didnt-receive-spacing">{{ $t('didntReceiveCode') }}</span>
                    <span
                        class="text-button"
                        @click="clickResendCode"
                        :class="{ 'disabled': isResendDisabled }"
                        style="cursor: pointer;"
                    >
                        {{ isResendDisabled ? `Resent: ${countdown}s` : $t('resend') }}
                    </span>
                </div>
            </div>

            <!-- Step 4: 重置成功 -->
            <div v-if="currentStep === 4" class="form-container success-container">
                <div class="back-button" @click="clickBackToCreate">
                    <el-icon color="#6B7280" size="16"><Back /></el-icon>
                    <span>{{ $t('back') }}</span>
                </div>
                <span class="title">{{ $t('passwordResetComplete') }}</span>
                <span class="description">{{ $t('passwordResetSuccess') }}</span>

                <div class="success-icon">
                    <l-img :src="'/static/images/success_icon.png'" w="32px" h="32px" />
                </div>

                <span class="success-message">
                    {{ $t('passwordResetMessage') }}
                </span>

                <l-button
                    :text="$t('returnToLogin')"
                    @onClick="clickReturnToLogin"
                />
            </div>
