<script setup>
import { ref, computed, onUnmounted } from 'vue';
import { useRouter } from 'vue-router';
import { useI18n } from 'vue-i18n';
import { routerToPrivacyPolicy, routerToTerms } from '@/router/navigation';
import LImg from '@/components/l-img.vue';
import LButton from '@/components/l-button.vue';
import { ROUTER_PATHS } from '@/router/constants';
import { ApiUser } from '@/api/api-user';
import { useDeviceDetection } from '@/utils/device-detector';

const router = useRouter();
const { t } = useI18n();
const { isMobile, windowWidth } = useDeviceDetection();
const appName = ref(import.meta.env.VITE_APP_TITLE);
const appLogo = ref(import.meta.env.VITE_APP_LOGO);
// 步骤管理
const currentStep = ref(1);

// 表单数据
const email = ref('');
const verificationCode = ref('');
const newPassword = ref('');
const confirmPassword = ref('');
const showPassword = ref(false);

// 表单验证
const emailError = ref('');
const verificationCodeError = ref('');
const passwordsNotMatch = ref(false);
const passwordTooShort = ref(false);
const passwordTooLong = ref(false);
const isLoading = ref(false);

// 倒计时相关
const countdown = ref(0);
const isResendDisabled = ref(false);
let countdownTimer = null;

// 表单验证计算属性
const isEmailValid = computed(() => {
    return email.value && !emailError.value;
});

const isVerificationCodeValid = computed(() => {
    return verificationCode.value && verificationCode.value.length === 8;
});

const arePasswordsValid = computed(() => {
    return newPassword.value.length >= 6 && newPassword.value.length <= 20
        && confirmPassword.value.length >= 6 && confirmPassword.value.length <= 20
        && newPassword.value === confirmPassword.value;
});

// 所有输入是否有效（用于完整的重置密码按钮验证）
const isAllInputsValid = computed(() => {
    return isVerificationCodeValid.value && arePasswordsValid.value;
});

// 根据设备类型动态计算 logo 尺寸
const logoSize = computed(() => {
    if (isMobile.value) {
        // 移动端根据屏幕宽度进一步细分
        if (windowWidth.value <= 375) {
            // 小屏手机 (iPhone SE, 小屏安卓等)
            return { width: '48px', height: '48px' };
        } else if (windowWidth.value <= 414) {
            // 中等屏幕手机 (iPhone 12/13/14 等)
            return { width: '52px', height: '52px' };
        } else {
            // 大屏手机 (iPhone Plus, 大屏安卓等)
            return { width: '56px', height: '56px' };
        }
    } else {
        // PC 端保持原有大小
        return { width: '60px', height: '60px' };
    }
});

// 根据设备类型动态计算 logo 文字大小
const logoTextSize = computed(() => {
    if (isMobile.value) {
        if (windowWidth.value <= 375) {
            return '20px';  // 小屏手机
        } else if (windowWidth.value <= 414) {
            return '22px';  // 中等屏幕手机
        } else {
            return '24px';  // 大屏手机
        }
    } else {
        return '26.4px';  // PC 端保持原有大小
    }
});


const clickTermsOfService = () => {
  // todo pxy 需要修改路径
  routerToTerms();
};

const clickPrivacyPolicy = () => {
  // todo pxy 需要修改路径
  routerToPrivacyPolicy();
};
// 验证方法
const validateEmail = () => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email.value) {
        emailError.value = t('emailRequired');
    } else if (!emailRegex.test(email.value)) {
        emailError.value = t('validEmail');
    } else {
        emailError.value = '';
    }
};

const validateVerificationCode = () => {
    // 只允许数字
    verificationCode.value = verificationCode.value.replace(/\D/g, '');

    if (verificationCode.value.length !== 8) {
        verificationCodeError.value = t('pleaseEnter8DigitCode');
    } else {
        verificationCodeError.value = '';
    }
};

const validatePasswords = () => {
    passwordTooShort.value = newPassword.value.length > 0  && newPassword.value.length < 6;
    passwordTooLong.value = newPassword.value.length > 6  && newPassword.value.length > 20;
    passwordsNotMatch.value = confirmPassword.value.length > 0 && newPassword.value !== confirmPassword.value;
};

// 开始倒计时
const startCountdown = () => {
    isResendDisabled.value = true;
    countdown.value = 60;

    countdownTimer = setInterval(() => {
        if (countdown.value > 1) {
            countdown.value--;
        } else {
            clearInterval(countdownTimer);
            isResendDisabled.value = false;
        }
    }, 1000);
};

// 切换显示密码
const toggleShowPassword = () => {
    showPassword.value = !showPassword.value;
};

// 步骤导航
const nextStep = () => {
    if (currentStep.value === 1) {
        // 从第1步跳到第3步（跳过原来的第2步）
        currentStep.value = 3;
    } else if (currentStep.value < 4) {
        currentStep.value++;
    }
};

// 通用API调用处理函数
const handleApiCall = async (apiFunction, successMessage, errorMessage, onSuccess = null) => {
    try {
        isLoading.value = true;
        const response = await apiFunction();

        if (response && response.code === 200) {
            const successMsg = response.data?.message || successMessage;
            ElMessage.success(successMsg);
            if (onSuccess) {
                await onSuccess(response);
            }
            return true;
        } else {
            const errorMsg = response?.message || errorMessage;
            return false;
        }
    } catch (error) {
        console.error(errorMessage, error);
        return false;
    } finally {
        isLoading.value = false;
    }
};

const clickSendVerificationCode = async () => {
    validateEmail();
    if (isEmailValid.value) {
        const success = await handleApiCall(
            () => ApiUser.requestResetPassword( email.value),
            'Verification code sent successfully',
            'Failed to send verification code',
            async () => {
                nextStep();
                startCountdown();
            }
        );
    }
};

const clickResetPassword = async () => {
    validateVerificationCode();
    validatePasswords();

    if (isAllInputsValid.value) {
        const success = await handleApiCall(
            () => ApiUser.resetPassword(email.value, verificationCode.value, newPassword.value, confirmPassword.value),
            'Password reset successfully',
            'Failed to reset password',
            async () => {
                nextStep();
            }
        );
    }
};

const clickResendCode = async () => {
    if (isResendDisabled.value) return;

    const success = await handleApiCall(
        () => ApiUser.requestResetPassword(email.value),
        'Verification code resent successfully',
        'Failed to resend verification code',
        async () => {
            startCountdown();
        }
    );
};

// 组件卸载时清除定时器
onUnmounted(() => {
    if (countdownTimer) {
        clearInterval(countdownTimer);
    }
});

const clickReturnToLogin = () => {
    router.push(ROUTER_PATHS.LOGIN);
};

const clickBackToLogin = () => {
    router.push(ROUTER_PATHS.LOGIN);
};

const clickBackToVerify = () => {
    currentStep.value = 1;
};

const clickBackToCreate = () => {
  router.push(ROUTER_PATHS.LOGIN);

};
</script>

